"""Transactions Service: JSON API + operations console UI (Flask) for the DevOps assignment."""

import math
import os
import platform
import secrets
import sqlite3
import time
from contextlib import contextmanager

from flask import Flask, flash, jsonify, redirect, render_template, request, url_for

app = Flask(__name__)
# Signs the session cookie that carries flash messages. On App Service SECRET_KEY is an app setting
# generated by Terraform (random_password) - no secret is hard-coded here. Without the variable
# (local runs, tests) a random per-process key is used, which is fine for a single process.
app.secret_key = os.environ.get("SECRET_KEY") or secrets.token_hex(32)
# Strip template-tag whitespace so the served HTML has no blank lines where Jinja blocks were.
app.jinja_env.trim_blocks = app.jinja_env.lstrip_blocks = True

# Azure App Service exposes a "SQLServer" connection string named "TransactionsDb"
# to the app as the environment variable SQLCONNSTR_TransactionsDb.
CONN_ENV = "SQLCONNSTR_TransactionsDb"
# App settings that are safe to show in the UI (never connection strings or keys).
SAFE_SETTINGS = ("APP_ENV", "APP_VERSION", "LOG_LEVEL", "FEATURE_FLAG_DEMO")

# Module-level sqlite connection, used only when no SQL Server is configured.
_sqlite = None
_schema_ready = False


def _is_mssql():
    """True when a SQL Server connection string is configured (T-SQL dialect)."""
    return bool(os.environ.get(CONN_ENV))


def _sql(stmt):
    """Adapt a '?'-placeholder statement to the active driver's paramstyle (pymssql uses %s).

    All statements are written once in sqlite/DB-API 'qmark' style; values are always passed
    as bound parameters, so this only ever rewrites the placeholder token, never data.
    """
    return stmt.replace("?", "%s") if _is_mssql() else stmt


def parse_sql_connection_string(cs):
    """Parse an ADO.NET-style connection string into pymssql.connect() kwargs.

    Example input (as produced by Terraform / App Service):
      "Server=tcp:host.database.windows.net,1433;Database=mydb;Uid=user;Pwd=secret;Encrypt=yes"
    Keys are case-insensitive; Uid/User ID and Pwd/Password aliases are both accepted.
    """
    parts = {}
    for item in cs.split(";"):
        if "=" in item:
            key, value = item.split("=", 1)
            parts[key.strip().lower()] = value.strip()
    # "Server=tcp:host,port" -> strip the protocol prefix and split off the optional port.
    server = parts.get("server", parts.get("data source", ""))
    if server.lower().startswith("tcp:"):
        server = server[4:]
    host, _, port = server.partition(",")
    return {
        "server": host,
        "port": int(port) if port else 1433,
        "database": parts.get("database", parts.get("initial catalog", "")),
        "user": parts.get("uid", parts.get("user id", "")),
        "password": parts.get("pwd", parts.get("password", "")),
    }


def reset_db():
    """Drop the in-memory sqlite DB so every test starts from a clean state."""
    global _sqlite, _schema_ready
    if _sqlite is not None:
        _sqlite.close()
    _sqlite, _schema_ready = None, False


def get_connection():
    """Return a DB connection: pymssql for SQL Server, sqlite3 in-memory otherwise."""
    global _sqlite, _schema_ready
    if _is_mssql():
        import pymssql  # lazy import: pure wheel, no ODBC driver; tests never need it

        cfg = parse_sql_connection_string(os.environ[CONN_ENV])
        conn = pymssql.connect(
            server=cfg["server"],
            port=cfg["port"],
            user=cfg["user"],
            password=cfg["password"],
            database=cfg["database"],
            login_timeout=30,
            autocommit=False,
        )
    else:
        if _sqlite is None:
            _sqlite = sqlite3.connect(":memory:", check_same_thread=False)
        conn = _sqlite
    if not _schema_ready:  # create the table on first use
        if _is_mssql():
            ddl = (
                "IF OBJECT_ID('Transactions') IS NULL CREATE TABLE Transactions ("
                "Id INT IDENTITY(1,1) PRIMARY KEY, Amount DECIMAL(18,2) NOT NULL, "
                "Description NVARCHAR(200), CreatedAt DATETIME DEFAULT GETDATE())"
            )
        else:
            ddl = (
                "CREATE TABLE IF NOT EXISTS Transactions ("
                "Id INTEGER PRIMARY KEY AUTOINCREMENT, Amount DECIMAL(18,2) NOT NULL, "
                "Description NVARCHAR(200), CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP)"
            )
        conn.cursor().execute(ddl)
        conn.commit()
        _schema_ready = True
    return conn


@contextmanager
def db_cursor():
    """Yield a cursor, commit on success and release the connection.

    SQL Server connections are opened per call and must be closed; the sqlite connection is the
    shared in-memory database and must stay open for the life of the process.
    """
    conn = get_connection()
    cur = conn.cursor()
    try:
        yield cur
        conn.commit()
    finally:
        cur.close()
        if _is_mssql():
            conn.close()


# ---------------------------------------------------------------------------
# Domain helpers shared by the JSON API and the UI (single implementation of each operation)
# ---------------------------------------------------------------------------
def _to_dict(row):
    """Convert a DB row (Id, Amount, Description, CreatedAt) into a JSON-friendly dict."""
    return {"id": row[0], "amount": float(row[1]), "description": row[2], "created_at": str(row[3])}


def parse_amount(value, allow_string=False):
    """Return the amount as float, or None when missing/invalid.

    JSON clients must send a real number (bool excluded); HTML forms submit strings, so the UI
    path opts into string parsing. NaN/inf are rejected for both.
    """
    if isinstance(value, bool):
        return None
    if isinstance(value, str) and allow_string:
        try:
            value = float(value.strip())
        except ValueError:
            return None
    if not isinstance(value, (int, float)) or not math.isfinite(value):
        return None
    return float(value)


def list_transactions(limit=20):
    """Return the most recent transactions, newest first (TOP vs LIMIT depends on dialect)."""
    limit = int(limit)  # never user input, but be explicit before formatting into SQL
    top, tail = (f"TOP {limit}", "") if _is_mssql() else ("", f"LIMIT {limit}")
    with db_cursor() as cur:
        cur.execute(
            f"SELECT {top} Id, Amount, Description, CreatedAt "  # nosec B608
            f"FROM Transactions ORDER BY Id DESC {tail}"
        )
        return [_to_dict(r) for r in cur.fetchall()]


def create_transaction(amount, description):
    """Insert a transaction (amount already validated) and return the stored record."""
    description = str(description or "")[:200]
    with db_cursor() as cur:
        if _is_mssql():  # T-SQL: OUTPUT returns the new identity in the same statement
            cur.execute(
                _sql(
                    "INSERT INTO Transactions (Amount, Description) "
                    "OUTPUT INSERTED.Id VALUES (?, ?)"
                ),
                (amount, description),
            )
            new_id = int(cur.fetchone()[0])
        else:  # sqlite: the new id is available via cursor.lastrowid
            cur.execute(
                _sql("INSERT INTO Transactions (Amount, Description) VALUES (?, ?)"),
                (amount, description),
            )
            new_id = cur.lastrowid
        cur.execute(
            _sql("SELECT Id, Amount, Description, CreatedAt FROM Transactions WHERE Id = ?"),
            (new_id,),
        )
        return _to_dict(cur.fetchone())


def get_stats():
    """Aggregate figures for the stat tiles: count, total amount, time of the last transaction."""
    with db_cursor() as cur:
        cur.execute("SELECT COUNT(*), COALESCE(SUM(Amount), 0), MAX(CreatedAt) FROM Transactions")
        count, total, last_at = cur.fetchone()
    return {
        "count": int(count),
        "total": float(total),
        "last_at": str(last_at) if last_at else None,
    }


def db_ping():
    """Time a SELECT 1 round-trip; the cheapest proof that the app -> DB path works."""
    backend = "sqlserver" if _is_mssql() else "sqlite"
    started = time.perf_counter()
    try:
        with db_cursor() as cur:
            cur.execute("SELECT 1")
            cur.fetchone()
        ok = True
    except Exception:  # pylint: disable=broad-exception-caught  # any driver error == unreachable
        ok = False
    return {"ok": ok, "latency_ms": int((time.perf_counter() - started) * 1000), "backend": backend}


# ---------------------------------------------------------------------------
# JSON API (contract used by the CI/CD smoke tests - do not change shapes)
# ---------------------------------------------------------------------------
@app.get("/health")
def health():
    """Liveness/readiness probe used by the App Service health check and monitoring."""
    return jsonify(
        status="ok",
        env=os.environ.get("APP_ENV", "local"),
        version=os.environ.get("APP_VERSION", "0.0.0"),
    )


@app.get("/health/deep")
def health_deep():
    """Dependency probe: ok when the database answers, degraded otherwise (always HTTP 200)."""
    db = db_ping()
    return jsonify(status="ok" if db["ok"] else "degraded", db=db)


@app.get("/transactions")
def api_list_transactions():
    """Last 20 transactions as JSON."""
    return jsonify(list_transactions())


@app.post("/transactions")
def api_create_transaction():
    """Create a transaction from JSON; 400 when amount is missing or not a number."""
    data = request.get_json(silent=True) or {}
    amount = parse_amount(data.get("amount"))
    if amount is None:
        return jsonify(error="'amount' is required and must be a number"), 400
    return jsonify(create_transaction(amount, data.get("description", ""))), 201


# ---------------------------------------------------------------------------
# Operations console UI
# ---------------------------------------------------------------------------
@app.get("/")
def index():
    """Render the console. Degrades gracefully (empty tiles/table) when the DB is unreachable."""
    cs = os.environ.get(CONN_ENV)
    db = db_ping()
    return render_template(
        "index.html",
        env=os.environ.get("APP_ENV", "local"),
        version=os.environ.get("APP_VERSION", "0.0.0")[:12],
        hostname=os.environ.get("WEBSITE_HOSTNAME", request.host),
        # Request-path strip: App Service platform variables with local fallbacks.
        site_name=os.environ.get("WEBSITE_SITE_NAME", "local"),
        private_ip=os.environ.get("WEBSITE_PRIVATE_IP", "snet-appsvc-integration"),
        sql_host=parse_sql_connection_string(cs)["server"] if cs else "sqlite :memory:",
        db=db,
        stats=get_stats() if db["ok"] else None,
        transactions=list_transactions() if db["ok"] else [],
        runtime={
            "python": platform.python_version(),
            "backend": "Azure SQL via pymssql" if cs else "SQLite in-memory",
            "instance": os.environ.get("WEBSITE_INSTANCE_ID", "local")[:8],
            "region": os.environ.get("REGION_NAME", "—"),
        },
        settings={key: os.environ.get(key, "—") for key in SAFE_SETTINGS},
    )


@app.post("/transactions/form")
def form_create_transaction():
    """HTML form handler: validate, create, redirect back (POST -> redirect -> GET pattern)."""
    amount = parse_amount(request.form.get("amount", ""), allow_string=True)
    if amount is None:
        flash("Amount is required and must be a number.", "error")
        return redirect(url_for("index"))
    record = create_transaction(amount, request.form.get("description", ""))
    flash(f"Transaction #{record['id']} added.", "success")
    return redirect(url_for("index"))


if __name__ == "__main__":
    # Bind to all interfaces: required inside the App Service / container sandbox.
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 8000)))  # nosec B104
